window.VO = [{"id":"o01","text":"You are under digital arrest.","at":0.24,"t0":0.12,"t1":2.22},{"id":"o02","text":"Do not hang up.","at":4.84,"t0":2.42,"t1":3.73},{"id":"n01","text":"Would you fall for this?","at":8.06,"t0":4.03,"t1":5.2},{"id":"n02","text":"Then find the three mistakes on this call.","at":12.3,"t0":6.15,"t1":8.16},{"id":"o03","text":"Again. A parcel in your name.","at":16.82,"t0":8.41,"t1":10.865},{"id":"o05","text":"Your pension account is frozen.","at":24.13,"t0":12.065,"t1":14.55},{"id":"o06","text":"Declare your gold, madam.","at":29.54,"t0":14.77,"t1":16.955},{"id":"o08","text":"Tell anyone, and they are arrested too.","at":34.41,"t0":17.205,"t1":19.9},{"id":"o09","text":"That is my team.","at":43.5,"t0":21.75,"t1":23.285},{"id":"n03","text":"You just looked at your door, didn't you?","at":47.17,"t0":23.585,"t1":25.235},{"id":"n04","text":"Even though his badge can't spell police.","at":50.77,"t0":25.385,"t1":27.445},{"id":"n05","text":"And even if it could, there's no such thing as a digital arrest.","at":55.19,"t0":27.595,"t1":30.925},{"id":"n06","text":"You only know that because somebody told you.","at":62.45,"t0":31.225,"t1":33.36},{"id":"n07","text":"Nobody told her.","at":67.22,"t0":33.61,"t1":34.69},{"id":"n08","text":"This was never your call.","at":71.08,"t0":35.54,"t1":36.95},{"id":"n09","text":"While you hunted for mistakes, she took off her bangles.","at":75.8,"t0":37.9,"t1":40.72},{"id":"n10","text":"She corrected spelling for thirty years, but she wasn't looking for his mistakes.","at":82.44,"t0":41.22,"t1":45.515},{"id":"n11","text":"She was trying to prove she hadn't made one.","at":91.73,"t0":45.865,"t1":47.91},{"id":"o10","text":"Madam.","at":101.52,"t0":50.76,"t1":51.53},{"id":"n12","text":"That was never his team.","at":103.86,"t0":51.93,"t1":53.295},{"id":"n13","text":"It was you.","at":107.19,"t0":53.595,"t1":54.39},{"id":"m01","text":"I'm fine, beta.","at":109.38,"t0":54.69,"t1":55.865},{"id":"m02","text":"You eat.","at":112.43,"t0":56.215,"t1":57.035},{"id":"n14","text":"So you did.","at":119.47,"t0":59.735,"t1":60.585},{"id":"n16","text":"You'd never fall for this.","at":125.07,"t0":62.535,"t1":63.945},{"id":"n17","text":"You would just believe her.","at":128.39,"t0":64.195,"t1":65.465},{"id":"n18","text":"Have you told your mother?","at":133.43,"t0":66.715,"t1":68.015},{"id":"n19","text":"Would she tell you?","at":137.23,"t0":68.615,"t1":69.66}];
